-- PAPER-LEARN-PROBATION-SETTLE-1 part 3 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 4872 to 4926 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_03 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_03 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_03 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_03)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_03 AS SELECT * FROM paper_learnings WHERE id IN (4872, 4873, 4878, 4881, 4886, 4887, 4888, 4890, 4891, 4896, 4897, 4902, 4905, 4906, 4907, 4908, 4909, 4910, 4915, 4916, 4917, 4918, 4922, 4925, 4926);

UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; belief): Design bets are filed as dated, probe-backed registry entries: belief_registry holds each belief the fleet acts on with a belief-<key> probe (DOCTRINE-1), and decision_log carries predicted_outcome and outcome_matched.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4872 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; ens): A second check that shares model family or data path is already counted as correlated: ENSEMBLE-POLICY-1 requires disjoint families, and BUDGET-SOFT-ROUTE-1 keeps the layers (cheapest models) rather than dropping them.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4873 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; goal-cost): Routed to goal external-impact-per-dollar (qnfo-fleet-control, adopted, program QNFO.OPS): cost per useful output is the fleet''s standing cost-per-impact goal; this learning supplies the per-loop view. Tracked there with a machine check written by the 2026-11-05 roadmap sweep.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4878 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; belief,pred): Dated check entries exist (belief_registry with a belief-<key> probe; decision_log predicted_outcome and outcome_matched, prediction_logged_share_7d 0.983). Calibrated probability estimates beyond matched or unmatched are not kept and no measured need for them is shown.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4881 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): sizing a metric trigger by the effect it claims to detect (a band and a minimum observation count instead of a bare threshold) is the same defect that issue measures (167 reopens on 44 tickets in 7 days).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4886 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; modeleval,guard): A candidate is measured against the production control on a fixed battery (qnfo-model-eval, cf_model_eval_runs) and a loop''s improvement is re-measured on the same metric after the change with keep-or-revert; a pool mean or self-comparison is not accepted as evidence (OUTPUT-QUALITY-LEDGER-1).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4887 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): The single-image null-versus-confirmation point is the paper''s own statistics. The trust ledger widens only fleet loop scopes from verified outcomes, and no scope widening is shown to have rested on one confirming incident. Re-propose with such a widening and its reversal.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4888 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; independent): Verification is already independent of the producing session: remediation probes are run by qnfo-fleet-control and scripts/remediation_consumer.py, a risky diff is read by two disjoint model families before merge, and a green pull request is merged by the stale-PR lane, not by its author.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4890 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): CLAIM-INTEGRITY-1 holds overstated empirical claims in pipeline papers and ENSEMBLE-POLICY-1 keeps scoring layers few; a second scorer for framing against demonstration has no measured miss behind it. Re-propose with a published artifact whose framing exceeded its demonstration.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4891 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; trust,verifylive): No counter-evidence is not accepted as a verified outcome: v_trust_ledger counts verified outcomes only, and an issue closes only with close_evidence from a live measurement.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4896 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The non-uniqueness of the paper''s length-scale construction is a point about its physics derivation; it implicates no fleet mechanism, and pipeline claims are already held by CLAIM-INTEGRITY-1 and the independent reviewer.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4897 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Eddington and Wyler as numerology is the paper''s treatment of its subject; flagging curve-fit derivations as speculative concerns physics content, not a fleet loop, and the pipeline reviewer already reads each paper.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4902 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; independent): Provisional status for internally validated outcomes exists in effect: scope widening uses verified outcomes only, probes are run by loops other than the filing session, and the review gate is two disjoint families.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4905 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): Scaffold-invariant measures are the fleet''s stated rule: OUTPUT-QUALITY-LEDGER-1 says clearing breaches, closing issues and raising a gate pass rate are not quality, outcome measures are read from output_quality_measures, and READER-YIELD-1 separates clicks from engaged readers.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4906 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The 2 to 4 to 1 hype index is the paper''s count of five hardware institutions'' public statements; fleet outreach claims are governed by CLAIM-INTEGRITY-1, outreach consent rules and the output-quality ledger. No fleet output is shown with a forward-claim excess.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4907 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; conflicts): Conflicts with PRIORITY-QUEUE-1 (owner directive 2026-10-03: dates are not important, order of priority is; no due dates are set), so there are no milestone dates for a slip rate to be computed from.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4908 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Doctrine amendments land by pull request with a version bump, and a diff that touches auth, a route, a trigger, a migration or a workflow is already read by two disjoint model families before it merges; no optimistic amendment adopted without dissent is shown. Re-propose with one.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4909 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; paper-convention): Refutation criteria stored beside doctrine claims are this paper''s own practice for its thesis; the fleet''s central reliability claims are measured by metrics with triggers, and no doctrine claim is shown to have outlived its refutation. Re-propose with such a claim.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4910 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; goal-cost): Routed to goal external-impact-per-dollar (qnfo-fleet-control, adopted, program QNFO.OPS), the standing goal for a unified cost per outcome; this learning supplies the unit (total spend per verified outcome with retries and checker spend). Tracked there with a machine check written by the 2026-11-05 roadmap sweep.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4915 AND fleet_status = 'probation';
